{
 "command": "cd services/notifier && find . -type f -not -path '*/node_modules/*' | head -50 && cat *.py 2>/dev/null | head -150",
 "description": "List notifier files and show source"
}

{
 "command": "for f in README.md pyproject.toml notifier/*.py tests/*.py; do echo \"=== $f\"; cat $f; done; ls ../../; cat ../../Makefile 2>/dev/null; grep -rn \"sink\\|MAIL_API\\|integration\" ../.. --include=*.py --include=*.toml --include=*.md --include=*.cfg --include=Makefile 2>/dev/null | head -30",
 "description": "Read notifier source, tests, and config"
}

{
 "command": "cd /tmp/mte-bf-notifier-sandbox-tmllseqh/ledgerline && cat pyproject.toml tests/test_payments.py; ls docs scripts; grep -rni \"sink\\|inbox\\|mailprovider\" docs scripts src 2>/dev/null | head",
 "description": "Check root pytest config and integration test pattern"
}

{
 "command": "cat docs/testing.md; ls docs/ops; grep -rli \"mail\\|notifier\" docs",
 "description": "Read testing docs and search for mail docs"
}

{
 "command": "cd /tmp/mte-bf-notifier-sandbox-tmllseqh/ledgerline/services/notifier && env -u MAIL_API_KEY -u MAIL_SINK_URL python -m pytest --import-mode=importlib tests -rs -q 2>&1 | tail -8",
 "description": "Run notifier tests without sandbox credentials"
}
